// The entry-level role pages (/jobs/entry-level/<role>): one curated record per starting job in white-collar work (Census major
// occupation groups 1 and 2), written once here and joined to live openings in live.ts. The text says what the job is, what
// a day looks like and which skills it uses; it makes no claim about pay or demand, which come from the open listings and
// BLS on the page itself. Pure data and rules, no I/O, so src/test/entry-roles.test.ts can hold every record to the format.

export interface EntryCategory { slug: string; name: string; blurb: string }

