export interface EntryRole {
  slug: string
  name: string
  cat: string
  /** The function label loadTitleInsights reads (BLS and AI-exposure context); null when none fits. */
  fn: string | null
  /** Title phrases that count a live opening as this role (lower case). */
  match: string[]
  /** What the job is, in one or two sentences. */
  what: string
  /** A day in the job, as short bullets. */
  tasks: string[]
  /** Skills the job uses, most important first. Every one is something a person can learn before the first day. */
  skills: string[]
  /** Slugs of roles people in this one commonly move to next. */
  next: string[]
}

