function parse(): EntryRole[] {
  return RAW.split('\n').map((line) => {
    const [slug, name, cat, fn, match, what, tasks, skills, next] = line.split('|')
    const list = (s: string) => s.split(';').map((x) => x.trim()).filter(Boolean)
    return { slug, name, cat, fn: fn || null, match: list(match).map((m) => m.toLowerCase()), what, tasks: list(tasks), skills: list(skills), next: list(next) }
  })
}

export const ENTRY_ROLES: EntryRole[] = parse()

const bySlug = new Map(ENTRY_ROLES.map((r) => [r.slug, r]))
export const entryRole = (slug: string): EntryRole | undefined => bySlug.get(slug)
export const entryCategory = (slug: string): EntryCategory | undefined => ENTRY_CATEGORIES.find((c) => c.slug === slug)
export const rolesInCategory = (cat: string): EntryRole[] => ENTRY_ROLES.filter((r) => r.cat === cat)

/** Roles to link to as "more jobs like this": the ones this role moves to, then the rest of its category. Slugs that are not roles are skipped. */
export function similarRoles(role: EntryRole, limit = 8): EntryRole[] {
  const out: EntryRole[] = []
  const add = (r: EntryRole | undefined) => { if (r && r.slug !== role.slug && !out.includes(r)) out.push(r) }
  role.next.forEach((s) => add(bySlug.get(s)))
  rolesInCategory(role.cat).forEach(add)
  return out.slice(0, limit)
}

// ── Matching a live opening to a role ────────────────────────────────────────────────────────────────────────────────

/** Words in a title that mark it as above entry level; an opening with one is not counted. "Executive" alone is not here (account executive). */
const ABOVE_ENTRY = /\b(senior|sr\.?|lead|principal|staff|manager|director|head of|vp|vice president|chief|supervisor|iii|iv|v|expert|architect|executive director)\b/i

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

/** The phrase as a word-bounded regex source (spaces match any run of spaces and hyphens). */
const phraseSource = (p: string) => esc(p).replace(/\s+/g, '[\\s-]+')

const compiled = ENTRY_ROLES.map((r) => ({ slug: r.slug, re: new RegExp(`(?:^|[^a-z0-9])(?:${r.match.map(phraseSource).join('|')})(?:[^a-z0-9]|$)`, 'i') }))

/** One Postgres regex that any role's phrases match, so the scan reads only candidate rows. */
export const ANY_ROLE_REGEX_PG = `(^|[^a-z0-9])(${ENTRY_ROLES.flatMap((r) => r.match.map(phraseSource)).join('|').replace(/\[\\s-\]\+/g, '[[:space:]-]+')})([^a-z0-9]|$)`

/**
 * The roles a title belongs to (usually one; "Business Development Representative" fits only BDR but a title can name two).
 * A title is above entry level when, once the role's own phrase is taken out, a word like "Senior" or "Director" is left:
 * "Account Manager" is a role, "Senior Account Manager" is not.
 */
export function rolesForTitle(title: string): string[] {
  const base = title.replace(/[\s]+[-–—|][\s]+.*$/, '').replace(/[(,].*$/, '')
  return compiled.filter((c) => {
    const m = c.re.exec(base)
    return !!m && !ABOVE_ENTRY.test(base.replace(m[0], ' '))
  }).map((c) => c.slug)
}

// ── Places ───────────────────────────────────────────────────────────────────────────────────────────────────────────

/** Open entry-level listings a (role, place) pair needs before it gets a page, and distinct employers (a page of one or two employers' listings is their job list, not a market). */
export const ENTRY_PLACE_BARS = { city: 6, state: 6, employers: 3 } as const
/** Listings a role needs nationally before its page says "open now"; below it the page still explains the job and says how to watch for openings. */
export const ENTRY_ROLE_MIN_JOBS = 5
